import { EasingFunction, ICircle, RGBAColor } from '@/types'

export class Circle implements ICircle
{
  x: number
  y: number
  destX: number
  destY: number
  width: number
  height: number
  delay: number
  color: RGBAColor

  constructor(
    x: number,
    y: number,
    width: number,
    height: number,
    delay: number,
    color: RGBAColor
  ) {
    this.x = x
    this.y = y

    this.destX = x
    this.destY = y

    this.width = width
    this.height = height

    this.delay = delay
    this.color = color
  }

  update(destX: number, destY: number, easingFunc?: EasingFunction): void
  {
    this.destX = destX
    this.destY = destY

    const ease = easingFunc ? easingFunc(1 / this.delay) : 1 / this.delay

    this.x += (this.destX - this.x) * ease
    this.y += (this.destY - this.y) * ease
  }

  draw(ctx: CanvasRenderingContext2D): void
  {
    ctx.lineWidth = 3
    ctx.strokeStyle = `rgba(${this.color.join(',')})`

    ctx.save()
    ctx.beginPath()
    ctx.translate(this.x - this.width, this.y - this.height)
    ctx.scale(this.width, this.height)
    ctx.arc(1, 1, 1, 0, 2 * Math.PI, false)
    ctx.restore()
    ctx.stroke()
  }
}
