import { RGBAColor, CirclesOptions, ICircle, EasingFunction } from '@/types'
import { Circle } from '@/circle'

import { linear } from '@/easing'

export class CirclesAnimation
{
  private canvas: HTMLCanvasElement
  private readonly ctx: CanvasRenderingContext2D

  private readonly numCircles: number
  private readonly maxDelay: number
  private readonly colorFrom: RGBAColor
  private readonly colorTo: RGBAColor

  private circles: ICircle[] = []
  private destX: number = 0
  private destY: number = 0

  private automate: boolean = true
  private automateRadius: number = 0
  private automatePosition: number = 0

  private winW: number = 0
  private winH: number = 0

  private circleMaxWidth: number = 0
  private circleMaxHeight: number = 0

  static run = (canvas: HTMLCanvasElement): void => {
    const animation = new CirclesAnimation(canvas)

    animation.init()
  }

  constructor(canvas: HTMLCanvasElement, options: CirclesOptions = {})
  {
    this.canvas = canvas
    this.ctx = canvas.getContext('2d') as CanvasRenderingContext2D

    this.numCircles = options.numCircles ?? 50
    this.maxDelay = options.maxDelay ?? 80
    this.colorFrom = options.colorFrom ?? [0, 100, 100, 0.5]
    this.colorTo = options.colorTo ?? [250, 250, 250, 0]

    this.reset = this.reset.bind(this)
  }

  init(): void
  {
    this.reset()
    this.bindEvents()
    this.loop(linear)
  }

  reset(): void
  {
    this.setupStage()
    this.createCircles()
  }

  setupStage(): void
  {
    this.winW = window.innerWidth
    this.winH = window.innerHeight
    this.automateRadius = this.winH * 0.25

    this.circleMaxWidth = Math.min(250, this.winW * 0.25)
    this.circleMaxHeight = this.circleMaxWidth * 0.25

    this.canvas.width = this.winW
    this.canvas.height = this.winH

    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height)
  }

  bindEvents(): void
  {
    this.canvas.addEventListener('mousemove', (e) => this.onMouseMove(e))
    this.canvas.addEventListener('mouseenter', () => (this.automate = false))
    this.canvas.addEventListener('mouseleave', () => (this.automate = true))
    window.addEventListener('resize', this.reset)
  }

  onMouseMove(e: MouseEvent): void
  {
    this.destX = e.pageX
    this.destY = e.pageY
  }

  createCircles(): void
  {
    this.circles = []

    const midX = this.winW >> 1
    const midY = this.winH >> 1
    const step = 1 / this.numCircles

    for (let i = this.numCircles - 1; i >= 0; i--) {
      const scale = step * i + step
      const delay = this.maxDelay * scale
      const width = this.circleMaxWidth * scale
      const height = this.circleMaxHeight * scale
      const color = this.getColor(i)

      this.circles.push(new Circle(midX, midY, width, height, delay, color))
    }
  }

  getColor(index: number): RGBAColor
  {
    const stepR = (this.colorTo[0] - this.colorFrom[0]) / (this.numCircles - 1)
    const red = Math.round(this.colorFrom[0] + stepR * index)
    const stepG = (this.colorTo[1] - this.colorFrom[1]) / (this.numCircles - 1)
    const green = Math.round(this.colorFrom[1] + stepG * index)
    const stepB = (this.colorTo[2] - this.colorFrom[2]) / (this.numCircles - 1)
    const blue = Math.round(this.colorFrom[2] + stepB * index)
    const stepA = (this.colorTo[3] - this.colorFrom[3]) / (this.numCircles - 1)
    const alpha = this.colorFrom[3] + stepA * index

    return [red, green, blue, alpha]
  }

  loop(easingFunc: EasingFunction): void
  {
    requestAnimationFrame(() => this.loop(easingFunc))

    this.ctx.globalCompositeOperation = 'source-over'
    this.ctx.fillStyle = 'rgba(1, 1, 1, .8)'
    this.ctx.fillRect(0, 0, this.canvas.width, this.canvas.height)
    this.ctx.globalCompositeOperation = 'lighter'

    if (this.automate) {
      this.destX = this.winW >> 1
      this.destY = (this.winH >> 1) + Math.sin(this.automatePosition) * this.automateRadius
      this.automatePosition += 0.02
    }

    for (const circle of this.circles) {
      circle.update(this.destX, this.destY, easingFunc)
      circle.draw(this.ctx)
    }
  }
}
